import re,json
with open('doc/superhero.md') as f: c=f.read()
with open('json/publisher.json') as f: pub={r['id']:r['publisher_name'] for r in json.load(f)['records']}
# Split by superhero sections
parts=c.split('##')
total_150_180=0
total_marvel_150_180=0
for p in parts:
  h=re.search(r'height.*?(\d+)',p,re.I)
  pb=re.search(r'publisher.*?(\d+)',p,re.I)
  if h and pb:
    ht=int(h.group(1))
    pbid=int(pb.group(1))
    if 150<=ht<=180:
      total_150_180+=1
      if pub.get(pbid)=='Marvel Comics':
        total_marvel_150_180+=1
print(f'Total heroes 150-180: {total_150_180}')
print(f'Marvel heroes 150-180: {total_marvel_150_180}')
if total_150_180>0:
  print(f'Percentage: {100*total_marvel_150_180/total_150_180:.2f}%')
else:
  print('No data')

